const { useEffect, useRef, useState } = React;

const DURATION_MS = 1000;
const WINDOW_MS = 1200;
const CHART = { width: 240, height: 72, pad: 6 };
const SCHEME = "height: auto / 0";
// height 从 auto 无法过渡：收起直接跳到 0，展开直接跳回 auto
const wrapperStyle = open => ({
  overflow: "hidden",
  transition: `height ${DURATION_MS}ms ease-in-out`,
  height: open ? undefined : 0,
});

const SkeletonLine = ({ className }) => (
  <div className={`cb-shimmer h-3 rounded-full bg-press ${className}`} />
);

const Component = () => {
  const wrapperRef = useRef(null);
  const innerRef = useRef(null);
  const frameRef = useRef(0);
  const [open, setOpen] = useState(true);
  const [fullHeight, setFullHeight] = useState(0);
  const [samples, setSamples] = useState([]);

  useEffect(() => {
    setFullHeight(innerRef.current.scrollHeight);
    return () => cancelAnimationFrame(frameRef.current);
  }, []);

  // 切换后逐帧采样容器实际高度，画出 1.2 秒内的高度曲线
  const toggle = () => {
    setOpen(value => !value);
    cancelAnimationFrame(frameRef.current);
    const points = [];
    let start = 0;
    const tick = now => {
      start ||= now;
      points.push([now - start, wrapperRef.current.getBoundingClientRect().height]);
      setSamples([...points]);
      if (now - start < WINDOW_MS) frameRef.current = requestAnimationFrame(tick);
    };
    frameRef.current = requestAnimationFrame(tick);
  };

  const scale = Math.max(fullHeight, ...samples.map(([, height]) => height), 1);
  const toX = time => (Math.min(time, WINDOW_MS) / WINDOW_MS) * CHART.width;
  const toY = height => CHART.height - CHART.pad - (height / scale) * (CHART.height - CHART.pad * 2);
  const line = samples.map(([time, height]) => `${toX(time)},${toY(height)}`).join(" ");
  const current = samples.length ? samples[samples.length - 1][1] : open ? fullHeight : 0;

  return (
    <div className="@container">
      <style>{`
        @scope {
          .cb-shimmer {
            background-image: linear-gradient(90deg, transparent, var(--tau-bg-surface-hover), transparent);
            background-size: 200% 100%;
            animation: cb-fold-shimmer 1.6s linear infinite;
          }
          @media (prefers-reduced-motion: reduce) {
            .cb-shimmer { animation: none; }
          }
        }
        @keyframes cb-fold-shimmer {
          from { background-position: 150% 0; }
          to { background-position: -50% 0; }
        }
      `}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_240px]">
        <div className="min-w-0">
          <div className="rounded-tau-md border border-line-1 bg-surface">
            <button
              type="button"
              onClick={toggle}
              className="flex w-full cursor-pointer items-center gap-2 rounded-tau-md px-3 py-2.5 text-left text-tau-body text-ink-1 hover:bg-hover"
            >
              <icons.ChevronRight
                className={`size-4 text-ink-3 transition-transform duration-300 ease-tau-out ${open ? "rotate-90" : ""}`}
              />
              <span>点击{open ? "隐藏" : "显示"}内容</span>
              <code className="ml-auto truncate rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-tiny text-ink-2">
                {SCHEME}
              </code>
            </button>
            <div ref={wrapperRef} style={wrapperStyle(open)}>
              <div ref={innerRef}>
                <div className="flex flex-col gap-3 border-t border-line-2 px-4 pb-4 pt-3">
                  <SkeletonLine className="w-2/5" />
                  <SkeletonLine className="w-full" />
                  <SkeletonLine className="w-full" />
                  <SkeletonLine className="w-11/12" />
                  <SkeletonLine className="w-3/5" />
                </div>
              </div>
            </div>
          </div>
        </div>
        <div className="flex flex-col gap-2 rounded-tau-md border border-line-1 p-3">
          <div className="flex items-baseline justify-between">
            <span className="text-tau-sm text-ink-3">高度变化</span>
            <span className="font-tau-mono text-tau-sm text-ink-2">
              {Math.round(current)}px / {fullHeight}px
            </span>
          </div>
          <svg
            viewBox={`0 0 ${CHART.width} ${CHART.height}`}
            preserveAspectRatio="none"
            className="h-[72px] w-full overflow-visible"
          >
            <line x1="0" x2={CHART.width} y1={toY(scale)} y2={toY(scale)} className="stroke-line-1" strokeDasharray="3 3" vectorEffect="non-scaling-stroke" />
            <line x1="0" x2={CHART.width} y1={toY(0)} y2={toY(0)} className="stroke-line-1" vectorEffect="non-scaling-stroke" />
            <line x1={toX(DURATION_MS)} x2={toX(DURATION_MS)} y1="0" y2={CHART.height} className="stroke-line-2" strokeDasharray="2 3" vectorEffect="non-scaling-stroke" />
            {line && (
              <polyline points={line} className="fill-none stroke-accent" strokeWidth="2" strokeLinejoin="round" vectorEffect="non-scaling-stroke" />
            )}
          </svg>
          <div className="flex justify-between font-tau-mono text-tau-tiny text-ink-3">
            <span>0s</span>
            <span>过渡结束 1s</span>
          </div>
          {!samples.length && (
            <p className="m-0 text-tau-meta text-ink-3">点击左侧标题，记录切换后的高度曲线</p>
          )}
        </div>
      </div>
    </div>
  );
};

